  const saveResources = async (ids: string[]) => { if (!ticket) return; try { const nextSet = new Set(ids); await Promise.all(resources.map((resource) => { const has = resource.ticket_ids.includes(ticket.id); if (has === nextSet.has(resource.id)) return Promise.resolve(); const ticketIds = has ? resource.ticket_ids.filter((id) => id !== ticket.id) : [...resource.ticket_ids, ticket.id]; return api.updateResource(resource.id, { name: resource.name, type: resource.type, url: resource.url, description: resource.description, attributes: resource.attributes, project_id: resource.project_id, milestone_ids: resource.milestone_ids, ticket_ids: ticketIds }); })); setResourceIds(ids); setResources((current) => current.map((item) => ({ ...item, ticket_ids: nextSet.has(item.id) ? [...item.ticket_ids.filter((id) => id !== ticket.id), ticket.id] : item.ticket_ids.filter((id) => id !== ticket.id) }))); setResourceOpen(false); } catch (err) { setActionError(errorMessage(err, "保存项目资源失败")); } };

